import json
from pathlib import Path


def load_metrics():
    bases = [Path.cwd()] + list(Path.cwd().parents)[:4]
    candidates = []
    for base in bases:
        candidates.extend([
            base / "boxoffice" / "final_total" / "training_metrics.json",
            base / "experiments" / "final_total_baseline" / "training_metrics.json",
        ])
    for p in candidates:
        if p.exists():
            try:
                with open(p, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                return None
    return None


metrics = load_metrics()
if metrics:
    for k in ["rmse", "mae", "mape_eps1", "smape", "wape", "r2"]:
        v = metrics.get(k)
        if isinstance(v, (int, float)):
            print(f"{k.upper()}: {v:.4f}")
        elif v is not None:
            print(f"{k.upper()}: {v}")
else:
    print("Holdout metrics not found in repo artifacts.")



